tasks.implementationGuide:
1. src/main.ts 수정:
```typescript
import { createApp } from 'vue';
import { createPinia } from 'pinia';
import naive from 'naive-ui';
import App from './App.vue';
import router from './router';
import './assets/index.css';

const app = createApp(App);

app.use(createPinia());
app.use(router);
app.use(naive);

app.mount('#app');

// Naive UI meta 설정
const meta = document.createElement('meta');
meta.name = 'naive-ui-style';
document.head.appendChild(meta);
```

2. src/types/global.d.ts 생성:
```typescript
import type {
  DialogApi,
  LoadingBarApi,
  MessageApi,
  NotificationApi,
} from 'naive-ui';

declare global {
  interface Window {
    $message: MessageApi;
    $dialog: DialogApi;
    $notification: NotificationApi;
    $loadingBar: LoadingBarApi;
  }
}

export {};
```

3. App.vue에서 global 설정:
```vue
<template>
  <n-config-provider>
    <n-message-provider>
      <n-dialog-provider>
        <n-notification-provider>
          <n-loading-bar-provider>
            <AppContent />
          </n-loading-bar-provider>
        </n-notification-provider>
      </n-dialog-provider>
    </n-message-provider>
  </n-config-provider>
</template>

<script setup lang="ts">
import {
  NConfigProvider,
  NMessageProvider,
  NDialogProvider,
  NNotificationProvider,
  NLoadingBarProvider,
  useMessage,
  useDialog,
  useNotification,
  useLoadingBar,
} from 'naive-ui';
import { onMounted } from 'vue';
import AppContent from './AppContent.vue';

onMounted(() => {
  window.$message = useMessage();
  window.$dialog = useDialog();
  window.$notification = useNotification();
  window.$loadingBar = useLoadingBar();
});
</script>
```

4. AppContent.vue 생성 (실제 라우팅 컴포넌트):
```vue
<template>
  <router-view />
</template>

<script setup lang="ts">
// 라우팅 컴포넌트
</script>
```

5. 사용 예시:
```typescript
// 컴포넌트 내부
window.$message.success('저장되었습니다!');
window.$message.error('오류가 발생했습니다.');
window.$message.warning('주의: 전월 데이터를 입력해주세요.');
window.$message.info('정보: 근무표 생성 중입니다.');

window.$dialog.warning({
  title: '경고',
  content: '전월 데이터가 입력되지 않았습니다.',
  positiveText: '확인',
  onPositiveClick: () => {
    console.log('확인 클릭');
  },
});

window.$notification.success({
  title: '근무표 생성 완료',
  content: '2025년 12월 근무표가 성공적으로 생성되었습니다.',
  duration: 3000,
});
```

